/* FolioArt. Subject-conditioned, latent-space engraved line illustrations.
 * Learned coefficients are embedded for offline inference. See train.py. */
(() => {
  'use strict';
  const models = {"physics":{"lines":24,"mean":"","scale":[0.001312369,0.000670285,0.000431353,0.000305688,0.00032919],"modes":"","explained":0.9815},"chemistry":{"lines":24,"mean":"","scale":[0.00076249,0.000523206,0.000399847,0.000239935,0.000184662],"modes":"","explained":0.9541},"biology":{"lines":28,"mean":"","scale":[0.000515093,0.000215394,0.000255184,0.000195435,4.9795e-05],"modes":"","explained":0.9958},"maths":{"lines":27,"mean":"","scale":[0.0007014,0.000541239,0.000267452,0.000309776,0.000211745],"modes":"","explained":0.9981}};
  const decoded = new Map();
  const points = 33;

  function bytes(encoded) {
    return Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
  }

  function parameters(subject) {
    if (decoded.has(subject)) return decoded.get(subject);
    const model = models[subject];
    const raw = bytes(model.mean);
    const reader = new DataView(raw.buffer);
    const mean = Float32Array.from({length:raw.length / 2}, (_, i) => reader.getInt16(i * 2, true) / 16000);
    const modes = new Int8Array(bytes(model.modes).buffer);
    const params = { mean, modes, scales:model.scale, lines:model.lines };
    decoded.set(subject, params);
    return params;
  }

  function randomSource(seed) {
    let h = 2166136261;
    for (const letter of String(seed ?? '')) h = Math.imul(h ^ letter.charCodeAt(0), 16777619);
    return () => {
      h = (h + 0x6D2B79F5) >>> 0;
      let x = Math.imul(h ^ (h >>> 15), 1 | h);
      x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
      return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
    };
  }

  function shape(subject, seed) {
    const { mean, modes, scales, lines } = parameters(subject);
    const random = randomSource(seed);
    const output = mean.slice();
    scales.forEach((scale, k) => {
      // Four independent uniforms give a bounded, approximately Gaussian latent.
      const z = (random() + random() + random() + random() - 2) * 1.62;
      const factor = scale * z;
      for (let i = 0; i < output.length; i++) output[i] += modes[k * output.length + i] * factor;
    });
    return { output, lines };
  }

  function draw(ctx, {x=0,y=0,width,height,subject='physics',seed=1,ink='#22645e'}={}) {
    if (!(width > 0 && height > 0)) return;
    subject = String(subject).toLowerCase();
    if (!Object.hasOwn(models,subject)) subject = 'physics';
    const { output, lines } = shape(subject,seed);
    let xMin=Infinity, yMin=Infinity, xMax=-Infinity, yMax=-Infinity;
    for (let i=0;i<output.length;i+=2) {
      xMin=Math.min(xMin,output[i]); xMax=Math.max(xMax,output[i]);
      yMin=Math.min(yMin,output[i+1]); yMax=Math.max(yMax,output[i+1]);
    }
    const radius = Math.min(width * .9 / (xMax-xMin),height * .86 / (yMax-yMin));
    ctx.save();
    try {
      ctx.beginPath(); ctx.rect(x,y,width,height);ctx.clip();
      ctx.translate(x+width/2,y+height/2);
      ctx.scale(radius,radius);
      ctx.translate(-(xMin+xMax)/2,-(yMin+yMax)/2);
      ctx.strokeStyle=ink;
      ctx.lineJoin='round';
      ctx.lineCap='round';
      for (let row=0;row<lines;row++) {
        const first = row * points * 2;
        let prevX = output[first], prevY=output[first+1];
        ctx.globalAlpha = (row%4 === 0 ? .94 : .69);
        ctx.lineWidth = row%4 === 0 ? .011 : .0078;
        ctx.beginPath();ctx.moveTo(prevX,prevY);
        for(let j=1;j<points;j++){
          const dx=output[first+j*2],dy=output[first+j*2+1];
          ctx.quadraticCurveTo(prevX,prevY,(dx+prevX)/2,(dy+prevY)/2);
          prevX=dx;prevY=dy;
        }
        ctx.lineTo(prevX,prevY);ctx.stroke();
      }
    } finally {
      ctx.restore();
    }
  }
  window.FolioArt=Object.freeze({ draw });
})();
